"use client";

import { ArrowRight } from "@nebutra/icons";
import type { ComponentPropsWithoutRef, ElementType, ReactNode } from "react";
import { cn } from "../utils";
import { Button } from "./button";

// =============================================================================
// Types
// =============================================================================

/**
 * Props for BentoGrid container
 *
 * @description
 * A responsive grid container for bento-style feature showcases.
 * Default is 3-column layout with auto-rows.
 *
 * **UX Scenarios:**
 * - Feature showcase sections
 * - Product capability grids
 * - Dashboard widget layouts
 * - Portfolio galleries
 * - Service offering displays
 */
export interface BentoGridProps extends ComponentPropsWithoutRef<"div"> {
  children: ReactNode;
  className?: string;
}

/**
 * Props for BentoCard item
 *
 * @description
 * Individual card within the BentoGrid with background slot, icon,
 * title, description, and hover-reveal CTA.
 *
 * **Features:**
 * - Background slot for custom content (images, animations, etc.)
 * - Icon with scale animation on hover
 * - Text content slides up on hover (desktop)
 * - CTA button reveals on hover (desktop), always visible on mobile
 */
export interface BentoCardProps extends ComponentPropsWithoutRef<"div"> {
  /** Card title */
  name: string;
  /** Card description */
  description: string;
  /** Icon component to display */
  Icon: React.ElementType;
  /** Background content (images, animations, gradients) */
  background?: ReactNode;
  /** Link URL for CTA */
  href?: string;
  /** CTA button text */
  cta?: string;
  /** Additional className for grid span control */
  className?: string;
}

// =============================================================================
// Components
// =============================================================================

/**
 * BentoGrid - Container for bento-style grid layouts
 *
 * @example
 * ```tsx
 * <BentoGrid className="lg:grid-cols-3">
 *   <BentoCard
 *     name="Feature 1"
 *     description="Description here"
 *     Icon={Sparkles}
 *     className="lg:col-span-2"
 *   />
 *   <BentoCard ... />
 * </BentoGrid>
 * ```
 */
export const BentoGrid = ({ children, className, ...props }: BentoGridProps) => {
  return (
    <div
      className={cn(
        "grid w-full auto-rows-[22rem] grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-3",
        className,
      )}
      {...props}
    >
      {children}
    </div>
  );
};

/**
 * BentoCard - Individual card with hover effects
 *
 * @example
 * ```tsx
 * <BentoCard
 *   name="AI Integration"
 *   description="Seamlessly integrate AI into your workflow"
 *   Icon={Brain}
 *   background={<GradientBackground />}
 *   href="/features/ai"
 *   cta="Learn more"
 *   className="lg:col-span-2 lg:row-span-2"
 * />
 * ```
 */
export const BentoCard = ({
  name,
  className,
  background,
  Icon,
  description,
  href,
  cta = "Learn more",
  ...props
}: BentoCardProps) => {
  const IconComponent = Icon as ElementType<{ className?: string }>;
  return (
    <div
      className={cn(
        "group relative col-span-1 flex flex-col justify-between overflow-hidden rounded-[var(--radius-xl)]",
        // Light styles
        "bg-background [box-shadow:0_0_0_1px_rgba(0,0,0,.03),0_2px_4px_rgba(0,0,0,.05),0_12px_24px_rgba(0,0,0,.05)]",
        // Dark styles
        "transform-gpu dark:bg-background dark:[border:1px_solid_rgba(255,255,255,.1)] dark:[box-shadow:0_-20px_80px_-20px_#ffffff1f_inset]",
        className,
      )}
      {...props}
    >
      {/* Background slot */}
      <div>{background}</div>

      {/* Content */}
      <div className="p-4">
        <div className="pointer-events-none z-10 flex transform-gpu flex-col gap-1 transition-[background-color,border-color,box-shadow,color,opacity,transform] duration-300 lg:group-hover:-translate-y-10">
          <IconComponent className="h-12 w-12 origin-left transform-gpu text-muted-foreground transition-[background-color,border-color,box-shadow,color,opacity,transform] duration-300 ease-in-out group-hover:scale-75" />
          <h3 className="text-xl font-semibold text-foreground">{name}</h3>
          <p className="max-w-lg text-muted-foreground">{description}</p>
        </div>

        {/* Mobile CTA (always visible) */}
        {href && (
          <div className="pointer-events-none flex w-full translate-y-0 transform-gpu flex-row items-center transition-[background-color,border-color,box-shadow,color,opacity,transform] duration-300 group-hover:translate-y-0 group-hover:opacity-100 lg:hidden">
            <Button variant="link" asChild size="sm" className="pointer-events-auto p-0">
              <a href={href}>
                {cta}
                <ArrowRight className="ms-2 h-4 w-4 rtl:rotate-180" />
              </a>
            </Button>
          </div>
        )}
      </div>

      {/* Desktop CTA (reveals on hover) */}
      {href && (
        <div className="pointer-events-none absolute bottom-0 hidden w-full translate-y-10 transform-gpu flex-row items-center p-4 opacity-0 transition-[background-color,border-color,box-shadow,color,opacity,transform] duration-300 group-hover:translate-y-0 group-hover:opacity-100 lg:flex">
          <Button variant="link" asChild size="sm" className="pointer-events-auto p-0">
            <a href={href}>
              {cta}
              <ArrowRight className="ms-2 h-4 w-4 rtl:rotate-180" />
            </a>
          </Button>
        </div>
      )}

      {/* Hover overlay */}
      <div className="pointer-events-none absolute inset-0 transform-gpu transition-[background-color,border-color,box-shadow,color,opacity,transform] duration-300 group-hover:bg-black/[.03] group-hover:dark:bg-muted/50" />
    </div>
  );
};

export default BentoGrid;

"use client";

import type { VariantProps } from "class-variance-authority";
import type * as React from "react";
import { cn } from "../utils/cn";
import { Slot } from "../utils/slot";
import { buttonVariants } from "./button-variants";

// ─── Spinner ──────────────────────────────────────────────────────────────────
// Uses @keyframes spinner from globals.css

function Spinner({ className }: { className?: string }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "block rounded-full border-2 border-current border-t-transparent animate-[spinner_0.6s_linear_infinite]",
        className,
      )}
    />
  );
}

// ─── Icon size class mapping ──────────────────────────────────────────────────

// iconSize (28/32/36px box) takes precedence over size (text-button scale)
// when both are present — an icon-only button sets iconSize, not size.
function getIconSizeClass(
  size: string | null | undefined,
  iconSize?: "sm" | "md" | "lg" | undefined,
): string {
  if (iconSize === "sm") return "[&>svg]:size-3.5"; // 14px, 28px box
  if (iconSize === "md") return "[&>svg]:size-3.5"; // 14px, 32px box
  if (iconSize === "lg") return "[&>svg]:size-4"; // 16px, 36px box
  switch (size) {
    case "tiny":
      return "[&>svg]:size-3"; // 12px
    case "sm":
      return "[&>svg]:size-3.5"; // 14px
    case "lg":
      return "[&>svg]:size-4.5"; // 18px
    default:
      return "[&>svg]:size-4"; // 16px
  }
}

function getSpinnerSizeClass(
  size: string | null | undefined,
  iconSize?: "sm" | "md" | "lg" | undefined,
): string {
  if (iconSize === "sm") return "size-3.5"; // 14px, 28px box
  if (iconSize === "md") return "size-3.5"; // 14px, 32px box
  if (iconSize === "lg") return "size-4"; // 16px, 36px box
  switch (size) {
    case "tiny":
      return "size-3"; // 12px
    case "sm":
      return "size-3.5"; // 14px
    case "lg":
      return "size-4.5"; // 18px
    default:
      return "size-4"; // 16px
  }
}

// ─── Shadow class mapping ─────────────────────────────────────────────────────

const SHADOW_CLASSES: Record<string, string> = {
  sm: "shadow-sm",
  md: "shadow-md",
  lg: "shadow-md",
};

function resolveShadowClass(shadow: boolean | "sm" | "md" | "lg" | undefined): string | undefined {
  if (!shadow) return undefined;
  const level = shadow === true ? "md" : shadow;
  return SHADOW_CLASSES[level];
}

// ─── ButtonContent (shared between Button & ButtonLink) ───────────────────────

interface ButtonContentProps {
  loading: boolean;
  prefix?: React.ReactNode | undefined;
  suffix?: React.ReactNode | undefined;
  size?: string | null | undefined;
  iconSize?: "sm" | "md" | "lg" | undefined;
  children?: React.ReactNode | undefined;
}

function ButtonContent({ loading, prefix, suffix, size, iconSize, children }: ButtonContentProps) {
  const iconSizeClass = getIconSizeClass(size, iconSize);

  return (
    <>
      {loading && <Spinner className={getSpinnerSizeClass(size, iconSize)} />}
      {prefix != null && (
        <span aria-hidden="true" className={cn("shrink-0", iconSizeClass)}>
          {prefix}
        </span>
      )}
      {children}
      {suffix != null && (
        <span aria-hidden="true" className={cn("shrink-0", iconSizeClass)}>
          {suffix}
        </span>
      )}
    </>
  );
}

// ─── Button ───────────────────────────────────────────────────────────────────

export interface ButtonProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "prefix">,
    VariantProps<typeof buttonVariants> {
  /** Render as a child element (Radix Slot — polymorphic) */
  asChild?: boolean;
  /** Show loading spinner and disable interaction */
  loading?: boolean;
  /** Icon or element rendered before children */
  prefix?: React.ReactNode;
  /** Icon or element rendered after children */
  suffix?: React.ReactNode;
  /** Elevation shadow level. `true` resolves to `"md"` */
  shadow?: boolean | "sm" | "md" | "lg";
  /**
   * Icon-only box size (28 / 32 / 36px) — only takes effect with
   * `shape="square"` or `shape="circle"`. Independent of `size`: use this
   * instead of `size` when the button carries only an icon, so its
   * dimensions don't inherit the text-button height/padding/font scale.
   */
  iconSize?: "sm" | "md" | "lg";
}

const Button = ({
  className,
  variant,
  size,
  shape,
  iconSize,
  asChild = false,
  loading = false,
  disabled,
  prefix,
  suffix,
  shadow,
  children,
  ref,
  ...props
}: ButtonProps & { ref?: React.Ref<HTMLButtonElement> | undefined }) => {
  const Comp = asChild ? Slot : "button";
  const isDisabled = Boolean(disabled || loading);
  const shadowClass = resolveShadowClass(shadow);

  return (
    <Comp
      ref={ref}
      className={cn(buttonVariants({ variant, size, shape, iconSize }), shadowClass, className)}
      disabled={isDisabled}
      aria-busy={loading || undefined}
      {...props}
    >
      {asChild ? (
        children
      ) : (
        <ButtonContent
          loading={loading}
          prefix={prefix}
          suffix={suffix}
          size={size}
          iconSize={iconSize}
        >
          {children}
        </ButtonContent>
      )}
    </Comp>
  );
};
Button.displayName = "Button";

// ─── ButtonLink ───────────────────────────────────────────────────────────────

export interface ButtonLinkProps
  extends Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, "prefix">,
    VariantProps<typeof buttonVariants> {
  /** Icon or element rendered before children */
  prefix?: React.ReactNode;
  /** Icon or element rendered after children */
  suffix?: React.ReactNode;
  /** Elevation shadow level. `true` resolves to `"md"` */
  shadow?: boolean | "sm" | "md" | "lg";
  /** Show loading spinner */
  loading?: boolean;
  /**
   * Icon-only box size (28 / 32 / 36px) — only takes effect with
   * `shape="square"` or `shape="circle"`. Independent of `size`: use this
   * instead of `size` when the link carries only an icon, so its
   * dimensions don't inherit the text-button height/padding/font scale.
   */
  iconSize?: "sm" | "md" | "lg";
}

const ButtonLink = ({
  className,
  variant,
  size,
  shape,
  iconSize,
  prefix,
  suffix,
  shadow,
  loading = false,
  children,
  ref,
  ...props
}: ButtonLinkProps & { ref?: React.Ref<HTMLAnchorElement> | undefined }) => {
  const shadowClass = resolveShadowClass(shadow);

  const loadingProps = loading
    ? {
        "aria-busy": "true" as const,
        "aria-disabled": "true" as const,
        tabIndex: -1,
      }
    : {};

  return (
    <a
      ref={ref}
      className={cn(
        buttonVariants({ variant, size, shape, iconSize }),
        shadowClass,
        loading && "pointer-events-none opacity-50",
        className,
      )}
      {...loadingProps}
      {...props}
    >
      <ButtonContent
        loading={loading}
        prefix={prefix}
        suffix={suffix}
        size={size}
        iconSize={iconSize}
      >
        {children}
      </ButtonContent>
    </a>
  );
};
ButtonLink.displayName = "ButtonLink";

export { Button, ButtonLink };

import { cva } from "class-variance-authority";

// Heights / weights from recipe.css (--control-height-*, --font-weight-medium).
// Focus ring uses shared ring token.
export const buttonVariants = cva(
  [
    "inline-flex items-center justify-center gap-2 whitespace-nowrap",
    "rounded-[var(--btn-default-radius,var(--radius-md))]",
    "text-[length:var(--control-font-size-md,0.875rem)] font-[number:var(--font-weight-medium,500)]",
    "transition-colors duration-micro ease-out",
    "disabled:pointer-events-none disabled:opacity-50",
    "aria-busy:cursor-wait",
  ].join(" "),
  {
    variants: {
      variant: {
        // Recipe-driven via packages/design/tokens/recipe.css (.btn-brand-default)
        default: "btn-brand-default",
        ink: "bg-[var(--neutral-12)] text-[var(--neutral-1)] ring-1 ring-inset ring-[color:var(--neutral-1)]/5 hover:bg-[var(--neutral-11)] hover:-translate-y-px active:translate-y-0 transition-[transform,background-color] duration-micro",
        destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90",
        outline: "border border-input bg-background hover:bg-accent hover:text-accent-foreground",
        secondary: "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-primary underline-offset-4 hover:underline",
        tertiary:
          "border border-transparent bg-transparent text-muted-foreground hover:bg-accent hover:text-accent-foreground hover:border-input",
        warning: "bg-warning text-warning-foreground hover:bg-warning/90",
      },
      size: {
        tiny: "h-[var(--control-height-tiny,1.5rem)] rounded-[var(--radius-sm)] px-2 text-[length:var(--control-font-size-tiny,0.6875rem)]",
        sm: "h-[var(--control-height-sm,2rem)] rounded-[var(--radius-sm)] px-3 text-[length:var(--control-font-size-sm,0.75rem)]",
        default:
          "h-[var(--control-height-md,2.5rem)] px-[var(--btn-default-padding-x,1rem)] py-[var(--btn-default-padding-y,0.5rem)]",
        lg: "h-[var(--control-height-lg,3rem)] rounded-[var(--radius-lg)] px-5 text-[length:var(--control-font-size-lg,1rem)]",
        icon: "h-[var(--control-height-md,2.5rem)] w-[var(--control-height-md,2.5rem)]",
      },
      shape: {
        default: "",
        // Radius from --btn-default-radius / --radius-md — brand-switchable.
        // Do not hardcode rounded-md here; a language must be able to retarget
        // the corner treatment of every icon trigger at once.
        square: "rounded-[var(--btn-default-radius,var(--radius-md))]",
        // Pill radius token, not Tailwind rounded-full — same 9999px default,
        // but a brand that ships a softer "circle" can override --radius-pill.
        circle: "rounded-[var(--radius-pill,9999px)]",
        pill: "rounded-[var(--radius-pill,9999px)]",
      },
      // Icon-only box size — orthogonal to `size` (which tunes text-button
      // height/padding/font together) and to `shape` (which picks the
      // corner treatment). Only takes effect combined with shape="square"
      // or shape="circle" (see compoundVariants below); every other
      // combination ignores it. 28/32/36 cover the icon-trigger sizes that
      // actually occur in the app — 24/40/48 are already reachable via
      // shape + size (tiny/default/lg). Heights read --control-height-icon-*
      // so density-aware Brand Packages can scale them with the ladder.
      iconSize: {
        sm: "", // 28px default
        md: "", // 32px default
        lg: "", // 36px default
      },
    },
    compoundVariants: [
      { shape: "square", size: "tiny", className: "w-[var(--control-height-tiny,1.5rem)] px-0" },
      { shape: "square", size: "sm", className: "w-[var(--control-height-sm,2rem)] px-0" },
      { shape: "square", size: "default", className: "w-[var(--control-height-md,2.5rem)] px-0" },
      { shape: "square", size: "lg", className: "w-[var(--control-height-lg,3rem)] px-0" },
      {
        shape: "circle",
        size: "tiny",
        className: "w-[var(--control-height-tiny,1.5rem)] px-0",
      },
      {
        shape: "circle",
        size: "sm",
        className: "w-[var(--control-height-sm,2rem)] px-0",
      },
      {
        shape: "circle",
        size: "default",
        className: "w-[var(--control-height-md,2.5rem)] px-0",
      },
      {
        shape: "circle",
        size: "lg",
        className: "w-[var(--control-height-lg,3rem)] px-0",
      },
      // iconSize wins over the size-driven box above — matched on shape +
      // iconSize only, so it applies regardless of whatever `size` was
      // passed (or left at its "default" fallback). Corner treatment stays
      // on the shape variant (token-backed); only the box is set here.
      {
        shape: "square",
        iconSize: "sm",
        className:
          "h-[var(--control-height-icon-sm,1.75rem)] w-[var(--control-height-icon-sm,1.75rem)] px-0",
      },
      {
        shape: "square",
        iconSize: "md",
        className:
          "h-[var(--control-height-icon-md,2rem)] w-[var(--control-height-icon-md,2rem)] px-0",
      },
      {
        shape: "square",
        iconSize: "lg",
        className:
          "h-[var(--control-height-icon-lg,2.25rem)] w-[var(--control-height-icon-lg,2.25rem)] px-0",
      },
      {
        shape: "circle",
        iconSize: "sm",
        className:
          "h-[var(--control-height-icon-sm,1.75rem)] w-[var(--control-height-icon-sm,1.75rem)] px-0",
      },
      {
        shape: "circle",
        iconSize: "md",
        className:
          "h-[var(--control-height-icon-md,2rem)] w-[var(--control-height-icon-md,2rem)] px-0",
      },
      {
        shape: "circle",
        iconSize: "lg",
        className:
          "h-[var(--control-height-icon-lg,2.25rem)] w-[var(--control-height-icon-lg,2.25rem)] px-0",
      },
    ],
    defaultVariants: {
      variant: "default",
      size: "default",
      shape: "default",
    },
  },
);
